mapper.select:
SELECT id, tenant_id, owner_id, device_id, state, sources_json, checks_json, expires_at <= clock_timestamp() AS expired,
       to_char(expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS expires_at
FROM c2k_runtime_readiness
WHERE tenant_id=#{tenantId}
  AND owner_id=#{ownerId}
  AND id=#{id}

mapper.update:
UPDATE c2k_runtime_readiness SET state='COMPLETE', checks_json=#{checks}
WHERE id=#{id}
  AND state='CHECKING'
  AND expires_at > clock_timestamp()

UPDATE c2k_runtime_readiness
SET expires_at=clock_timestamp()
WHERE id=#{id}

mapper.delete:
DELETE FROM c2k_runtime_readiness
WHERE tenant_id=#{tenantId}
  AND owner_id=#{ownerId}
  AND expires_at <= clock_timestamp()
